//
//  ClipboardPolicy.swift
//  PixelHandCore
//
//  S10: clipboard text sync. The rules both apps follow, re-implemented
//  from Sill's documented behaviour (no code copied):
//
//  - Text only, up to `maxTextBytes`. Longer text is not sent (the Mac
//    logs it; the remote says so).
//  - Opt-in per remote ("Share clipboard", off by default). The Mac sends
//    its clipboard only to remotes that asked (`sharing.clipboardSync`).
//  - Never while the Mac is locked, and never an item a password manager
//    or another app marked concealed, transient or auto-generated (the
//    nspasteboard.org conventions).
//  - The remote never reads its own clipboard by itself: the person pastes
//    into it with the system paste control, which asks nothing.
//  - What the Mac put on its clipboard because a remote asked is not sent
//    back to remotes as a change (`ClipboardEcho`).
//

import Foundation

public enum ClipboardPolicy {
    /// Largest clipboard text either side sends (UTF-8 bytes): the
    /// protocol's string limit, so a message is never refused for size.
    public static let maxTextBytes = ProtocolLimits.maxStringLength

    /// How often the Mac looks at its pasteboard's change count. macOS has
    /// no change notification; this is cheap (one integer read).
    public static let macPollInterval: Duration = .milliseconds(500)

    /// Pasteboard types (UTIs) that mark an item as not to be shared.
    /// See nspasteboard.org.
    public static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        // Older password-manager markers.
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    /// Whether an item with `types` and `text` may be shared.
    public static func shouldShare(text: String?, types: [String]) -> Bool {
        guard let text, !text.isEmpty else { return false }
        guard text.utf8.count <= maxTextBytes else { return false }
        return types.allSatisfy { !privateTypes.contains($0) }
    }

    /// Whether text a remote sent may go on the Mac's clipboard.
    public static func isAcceptable(remoteText text: String) -> Bool {
        !text.isEmpty && text.utf8.count <= maxTextBytes
    }
}

/// Remembers the change the Mac made itself, so it isn't echoed back.
public struct ClipboardEcho: Equatable, Sendable {
    private var ownChangeCount: Int?

    public init() {}

    /// The Mac wrote the pasteboard for a remote; `changeCount` is the
    /// pasteboard's count right after.
    public mutating func wrote(changeCount: Int) {
        ownChangeCount = changeCount
    }

    /// Whether a change seen at `changeCount` should go to remotes.
    public func shouldBroadcast(changeCount: Int) -> Bool {
        changeCount != ownChangeCount
    }
}
